const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const taipei = ee.Geometry.Point([121.56, 25.03]);
  const region = taipei.buffer(10000); // 10km radius around Taipei

  // 2. Data Acquisition
  // MODIS LST Day (MOD11A1) - daily 1km resolution
  const lstCollection = ee.ImageCollection('MODIS/006/MOD11A1')
    .select('LST_Day_1km');

  // Quality masking function
  function maskLowQuality(image) {
    const qa = image.select('QC_Day');
    // Keep only pixels with good quality (bits 0-1 = 00)
    const mask = qa.bitwiseAnd(3).eq(0);
    return image.updateMask(mask);
  }

  // Baseline period: Jan 17-24, 2001-2010
  let baselineImages = [];
  for (let year = 2001; year <= 2010; year++) {
    const yearCol = lstCollection
      .filterBounds(taipei)
      .filterDate(`${year}-01-17`, `${year}-01-25`)
      .map(maskLowQuality);
    baselineImages.push(yearCol);
  }
  const baselineCol = ee.ImageCollection(baselineImages.flat());

  // 2016 period: Jan 17-24
  const col2016 = lstCollection
    .filterBounds(taipei)
    .filterDate('2016-01-17', '2016-01-25')
    .map(maskLowQuality);

  const baselineSize = baselineCol.size().getInfo();
  const size2016 = col2016.size().getInfo();

  console.log(`Baseline (2001-2010) images: ${baselineSize}`);
  console.log(`2016 images: ${size2016}`);

  if (baselineSize === 0 || size2016 === 0) {
    console.log("Insufficient data for comparison.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate mean LST for each period
  const baselineMean = baselineCol.mean();
  const mean2016 = col2016.mean();

  // 4. Reduce to get statistics
  const baselineStats = baselineMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2016 = mean2016.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const baselineLST = baselineStats['LST_Day_1km_mean'];
  const baselineCount = baselineStats['LST_Day_1km_count'];
  const lst2016 = stats2016['LST_Day_1km_mean'];
  const count2016 = stats2016['LST_Day_1km_count'];

  console.log(`Baseline valid pixels: ${baselineCount}`);
  console.log(`2016 valid pixels: ${count2016}`);

  if (!baselineCount || baselineCount === 0 || !count2016 || count2016 === 0) {
    console.log("No valid pixels after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Convert from Kelvin scale factor (0.02) to Celsius
  const baselineTempC = (baselineLST * 0.02) - 273.15;
  const temp2016C = (lst2016 * 0.02) - 273.15;

  console.log(`Baseline LST (2001-2010): ${baselineTempC.toFixed(2)}°C`);
  console.log(`2016 LST: ${temp2016C.toFixed(2)}°C`);

  // 5. Validation & Final Answer
  if (baselineLST == null || lst2016 == null || 
      isNaN(baselineTempC) || isNaN(temp2016C) ||
      baselineTempC < -40 || baselineTempC > 60 ||
      temp2016C < -40 || temp2016C > 60) {
    console.log("Invalid temperature calculation.");
    console.log("<answer>C3</answer>");
    return;
  }

  const difference = temp2016C - baselineTempC;
  console.log(`Temperature difference: ${difference.toFixed(2)}°C`);

  if (temp2016C < baselineTempC) {
    console.log("2016 LST decreased compared to baseline.");
    console.log("<answer>A</answer>");
  } else {
    console.log("2016 LST did not decrease compared to baseline.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
